var R={"RELOJERO": {"n": "Relojero", "t": "ALDEANO", "d": "Empiezas sabiendo a cuántos pasos está el Demonio de su Esbirro más cercano.", "i": "data:image/png;base64,"}, "ABUELA": {"n": "Abuela", "t": "ALDEANO", "d": "Empiezas conociendo 1 jugador bueno y su personaje. Si el Demonio le mata, tú también mueres.", "i": "data:image/png;base64,"}, "BIBLIOTECARIO": {"n": "Bibliotecario", "t": "ALDEANO", "d": "Empiezas conociendo que 1 de 2 jugadores es un Forastero particular (o que hay 0 en juego).", "i": "data:image/png;base64,"}, "EMPÁTICO": {"n": "Empático", "t": "ALDEANO", "d": "Cada noche sabes cuántos de tus vecinos vivos son malos.", "i": "data:image/png;base64,"}, "PITONISA": {"n": "Pitonisa", "t": "ALDEANO", "d": "Cada noche elige 2 jugadores: sabes si alguno es el Demonio. Hay 1 jugador bueno que aparece como Demonio para ti.", "i": "data:image/png;base64,"}, "FLORISTA": {"n": "Florista", "t": "ALDEANO", "d": "Cada noche* descubres si el Demonio ha votado hoy.", "i": "data:image/png;base64,"}, "ENTERRADOR": {"n": "Enterrador", "t": "ALDEANO", "d": "Cada noche* descubres qué personaje ha muerto por ejecución hoy.", "i": "data:image/png;base64,"}, "BORRACHO": {"n": "Borracho", "t": "FORASTERO", "d": "No sabes que eres el Borracho. Crees que eres un Aldeano, pero no lo eres.", "i": "data:image/png;base64,"}, "RECLUSO": {"n": "Recluso", "t": "FORASTERO", "d": "Puedes aparecer como malo y como Esbirro o Demonio, aunque estés muerto.", "i": "data:image/png;base64,"}, "ENVENENADOR": {"n": "Envenenador", "t": "ESBIRRO", "d": "Cada noche elige 1 jugador: está envenenado esta noche y el día de mañana.", "i": "data:image/png;base64,"}, "ABOGADO DEL DIABLO": {"n": "Abogado del diablo", "t": "ESBIRRO", "d": "Cada noche elige 1 jugador vivo (diferente al de la noche anterior): si es ejecutado mañana, no muere.", "i": "data:image/png;base64,"}, "ESPÍA": {"n": "Espía", "t": "ESBIRRO", "d": "Cada noche ves el Grimorio. Puedes aparecer como bueno y como Aldeano o Forastero, aunque estés muerto.", "i": "data:image/png;base64,"}, "DIABLILLO": {"n": "Diablillo", "t": "DEMONIO", "d": "Cada noche* elige 1 jugador: muere. Si te matas de esta forma, un Esbirro se convierte en el Diablillo.", "i": "data:image/png;base64,"}, "MONJE": {"n": "Monje", "t": "ALDEANO", "d": "Cada noche* elige 1 jugador (no a ti): está a salvo del Demonio esta noche.", "i": "data:image/png;base64,"}, "ARTISTA": {"n": "Artista", "t": "ALDEANO", "d": "Una vez por partida, durante el día, hazle en privado al Narrador una pregunta de sí o no.", "i": "data:image/png;base64,"}, "TAHÚR": {"n": "Tahúr", "t": "ALDEANO", "d": "Cada noche* elige 1 jugador e intenta adivinar su personaje: si fallas, mueres.", "i": "data:image/png;base64,"}, "GUARDIÁN DE CUERVOS": {"n": "Guardián de cuervos", "t": "ALDEANO", "d": "Si mueres por la noche, te despiertan para que elijas 1 jugador: descubres su personaje.", "i": "data:image/png;base64,"}, "ALCALDE": {"n": "Alcalde", "t": "ALDEANO", "d": "Si sólo quedan 3 jugadores vivos y no hay ejecución, tu bando gana. Si mueres por la noche, en vez de eso puede morir otro jugador.", "i": "data:image/png;base64,"}, "BUFÓN": {"n": "Bufón", "t": "ALDEANO", "d": "La primera vez que mueras, no mueres.", "i": "data:image/png;base64,"}, "NIÑA DE LA LUNA": {"n": "Niña de la Luna", "t": "FORASTERO", "d": "Cuando descubras que has muerto, elige públicamente 1 jugador vivo. Esta noche, si era bueno, muere.", "i": "data:image/png;base64,"}, "SANTO": {"n": "Santo", "t": "FORASTERO", "d": "Si mueres por ejecución, tu equipo pierde.", "i": "data:image/png;base64,"}, "ASESINO": {"n": "Asesino", "t": "ESBIRRO", "d": "Una vez por partida, por la noche*, elige 1 jugador: muere, incluso si por otro motivo no pudiera.", "i": "data:image/png;base64,"}, "MUJER ESCARLATA": {"n": "Mujer escarlata", "t": "ESBIRRO", "d": "Si hay 5 o más jugadores vivos y el Demonio muere, te conviertes en el Demonio. (No cuentan los viajeros)", "i": "data:image/png;base64,"}, "BARÓN": {"n": "Barón", "t": "ESBIRRO", "d": "Hay Forasteros extra en juego. [+2 Forasteros]", "i": "data:image/png;base64,"}, "CHEF": {"n": "Chef", "t": "ALDEANO", "d": "Empiezas sabiendo cuántas parejas de jugadores malos hay.", "i": "data:image/png;base64,"}, "INVESTIGADOR": {"n": "Investigador", "t": "ALDEANO", "d": "Empiezas conociendo que 1 de 2 jugadores es un Esbirro particular.", "i": "data:image/png;base64,"}, "LAVANDERA": {"n": "Lavandera", "t": "ALDEANO", "d": "Empiezas conociendo que 1 de 2 jugadores es un Aldeano particular.", "i": "data:image/png;base64,"}, "MAYORDOMO": {"n": "Mayordomo", "t": "FORASTERO", "d": "Cada noche elige 1 jugador (no a ti): mañana sólo puedes votar si ese jugador está votando.", "i": "data:image/png;base64,"}, "EXTERMINADOR": {"n": "Exterminador", "t": "ALDEANO", "d": "Una vez por partida, durante el día, elige públicamente 1 jugador: si es el Demonio, muere.", "i": "data:image/png;base64,"}, "SOLDADO": {"n": "Soldado", "t": "ALDEANO", "d": "Estás a salvo del Demonio.", "i": "data:image/png;base64,"}, "VIRGEN": {"n": "Virgen", "t": "ALDEANO", "d": "La primera vez que te nominen, si quien nomina es Aldeano, es ejecutado inmediatamente.", "i": "data:image/png;base64,"}, "SOÑADOR": {"n": "Soñador", "t": "ALDEANO", "d": "Cada noche elige 1 jugador (no a ti o viajeros): descubres 1 personaje bueno y 1 personaje malo, 1 de ellos es correcto.", "i": "data:image/png;base64,"}, "ENCANTADOR DE SERPIENTES": {"n": "Encantador de Serpientes", "t": "ALDEANO", "d": "Cada noche elige 1 jugador vivo: si es el Demonio intercambiáis personajes y alineamiento y después está envenenado.", "i": "data:image/png;base64,"}, "MATEMÁTICO": {"n": "Matemático", "t": "ALDEANO", "d": "Cada noche sabes cuántas habilidades de personajes han funcionado anormalmente (desde el amanecer) por las habilidades de otros personajes.", "i": "data:image/png;base64,"}, "PREGONERO": {"n": "Pregonero", "t": "ALDEANO", "d": "Cada noche* descubres si 1 Esbirro ha nominado hoy.", "i": "data:image/png;base64,"}, "ORÁCULO": {"n": "Oráculo", "t": "ALDEANO", "d": "Cada noche* sabes cuántos jugadores muertos son malos.", "i": "data:image/png;base64,"}, "MUTANTE": {"n": "Mutante", "t": "FORASTERO", "d": "Si estás loco sobre que eres un Forastero, puedes ser ejecutado.", "i": "data:image/png;base64,"}, "ADORABLE": {"n": "Adorable", "t": "FORASTERO", "d": "Cuando mueras, 1 jugador está borracho.", "i": "data:image/png;base64,"}, "GEMELA MALVADA": {"n": "Gemela malvada", "t": "ESBIRRO", "d": "Tú y 1 jugador del equipo contrario os conocéis. Si el jugador bueno es ejecutado, los malos ganan. Los buenos no pueden ganar si ambos vivís.", "i": "data:image/png;base64,"}, "BRUJA": {"n": "Bruja", "t": "ESBIRRO", "d": "Cada noche elige 1 jugador: si mañana nomina, muere. Si sólo hay 3 jugadores vivos pierdes esta habilidad.", "i": "data:image/png;base64,"}, "FANG GU": {"n": "Fang Gu", "t": "DEMONIO", "d": "Cada noche* elige 1 jugador: muere. El primer Forastero que mates se convierte en Fang Gu malo y, en vez de morir, mueres tú. [+1 Forastero]", "i": "data:image/png;base64,"}, "VIGORMORTIS": {"n": "Vigormortis", "t": "DEMONIO", "d": "Cada noche* elige 1 jugador: muere. Los Esbirros que mates mantienen su habilidad y 1 Aldeano vecino suyo está envenenado. [-1 Forastero]", "i": "data:image/png;base64,"}, "ERUDITO": {"n": "Erudito", "t": "ALDEANO", "d": "Cada día puedes visitar en privado al Narrador para que te diga 2 informaciones: 1 es cierta y 1 es falsa.", "i": "data:image/png;base64,"}, "COSTURERA": {"n": "Costurera", "t": "ALDEANO", "d": "Una vez por partida, por la noche, elige 2 jugadores (no a ti): descubres si son del mismo alineamiento.", "i": "data:image/png;base64,"}, "FILÓSOFO": {"n": "Filósofo", "t": "ALDEANO", "d": "Una vez por partida, por la noche, elige 1 personaje bueno: ganas su habilidad. Si el personaje está en juego, está borracho.", "i": "data:image/png;base64,"}, "MALABARISTA": {"n": "Malabarista", "t": "ALDEANO", "d": "En tu primer día declara públicamente el personaje de hasta 5 jugadores. Esta noche sabes cuántos has acertado.", "i": "data:image/png;base64,"}, "SABIO": {"n": "Sabio", "t": "ALDEANO", "d": "Si el Demonio te mata descubres que es 1 de 2 jugadores.", "i": "data:image/png;base64,"}, "BARBERO": {"n": "Barbero", "t": "FORASTERO", "d": "Cuando mueras, el Demonio puede elegir 2 jugadores por la noche (no otro Demonio) para que intercambien personajes.", "i": "data:image/png;base64,"}, "PATOSO": {"n": "Patoso", "t": "FORASTERO", "d": "Cuando descubras que has muerto, elige públicamente 1 jugador vivo: si es malo, tu equipo pierde.", "i": "data:image/png;base64,"}, "CERENOVUS": {"n": "Cerenovus", "t": "ESBIRRO", "d": "Cada noche, elige 1 jugador y 1 personaje bueno: mañana el jugador está loco sobre que es ese personaje o puede ser ejecutado.", "i": "data:image/png;base64,"}, "PIT-HAG": {"n": "Pit-Hag", "t": "ESBIRRO", "d": "Cada noche* elige 1 jugador y 1 personaje al que se convierte (si no está en juego). Si creas un Demonio, las muertes esta noche son arbitrarias.", "i": "data:image/png;base64,"}, "NO DASHII": {"n": "No Dashii", "t": "DEMONIO", "d": "Cada noche* elige 1 jugador: muere. Tus 2 vecinos Aldeanos están envenenados.", "i": "data:image/png;base64,"}, "VORTOX": {"n": "Vortox", "t": "DEMONIO", "d": "Cada noche* elige 1 jugador: muere. Las habilidades de los Aldeanos dan información falsa. Cada día, si nadie es ejecutado, ganan los malos.", "i": "data:image/png;base64,"}};
